"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq
from collections.abc import Iterator

Cell = tuple[int, int]  # (row, col)

_ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def _find(grid: list[str], want: str) -> Cell | None:
    for r, row in enumerate(grid):
        c = row.find(want)
        if c != -1:
            return (r, c)
    return None


def _neighbours(cell: Cell, grid: list[str]) -> Iterator[tuple[Cell, int]]:
    r, c = cell
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]):
            cost = _ENTER_COST.get(grid[nr][nc])
            if cost is not None:
                yield (nr, nc), cost


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = _find(grid, "S")
    goal = _find(grid, "G")
    if start is None or goal is None:
        return None

    best = {start: _ENTER_COST["S"]}
    previous: dict[Cell, Cell] = {}
    queue: list[tuple[int, int, Cell]] = [(best[start], 0, start)]
    steps = 0
    while queue:
        cost, _, cell = heapq.heappop(queue)
        if cost > best.get(cell, float("inf")):
            continue
        if cell == goal:
            path = [cell]
            while path[-1] in previous:
                path.append(previous[path[-1]])
            path.reverse()
            return path
        for nxt, step_cost in _neighbours(cell, grid):
            new_cost = cost + step_cost
            if new_cost < best.get(nxt, float("inf")):
                best[nxt] = new_cost
                previous[nxt] = cell
                steps += 1
                heapq.heappush(queue, (new_cost, steps, nxt))
    return None

